// Test to verify the fixes for group cover and user profile picture deletion

// Simulate the group cover removal fix
async function testGroupCoverRemoval() {
    console.log('Testing group cover removal fix...');

    // Simulate the fixed removeCover function
    const fields = ['cover:url', 'cover:thumb:url'];
    const values = {
        'cover:url': '/assets/uploads/files/groupCover-test.png',
        'cover:thumb:url': '/assets/uploads/files/groupCoverThumb-test.png'
    };

    // The fix: now we await file.delete for each file
    await Promise.all(fields.map(async (field) => {
        if (!values[field] || !values[field].startsWith('/assets/uploads/files/')) {
